WITH
case_set AS (SELECT DISTINCT c.concept_id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria` c JOIN (SELECT CAST(cr.id AS STRING) id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria` cr WHERE concept_id IN (140168,36715780,37205056,37205057,4031141,4031142,4031649,4063433,4223485) AND full_text LIKE '%_rank1]%') a ON (c.path LIKE CONCAT('%.',a.id,'.%') OR c.path LIKE CONCAT('%.',a.id) OR c.path LIKE CONCAT(a.id,'.%') OR c.path=a.id) WHERE c.is_standard=1 AND c.is_selectable=1),
arthritis_set AS (SELECT DISTINCT c.concept_id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria` c JOIN (SELECT CAST(cr.id AS STRING) id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria` cr WHERE concept_id IN (81931,40319772,4083682,46274123) AND full_text LIKE '%_rank1]%') a ON (c.path LIKE CONCAT('%.',a.id,'.%') OR c.path LIKE CONCAT('%.',a.id) OR c.path LIKE CONCAT(a.id,'.%') OR c.path=a.id) WHERE c.is_standard=1 AND c.is_selectable=1),
exclude_set AS (SELECT DISTINCT c.concept_id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria` c JOIN (SELECT CAST(cr.id AS STRING) id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria` cr WHERE concept_id IN (140168,36715780,37205056,37205057,4031141,4031142,4031649,4063433,4223485,81931,40319772,4083682,46274123) AND full_text LIKE '%_rank1]%') a ON (c.path LIKE CONCAT('%.',a.id,'.%') OR c.path LIKE CONCAT('%.',a.id) OR c.path LIKE CONCAT(a.id,'.%') OR c.path=a.id) WHERE c.is_standard=1 AND c.is_selectable=1),
drug_roots AS (SELECT DISTINCT c.concept_id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria` c JOIN (SELECT CAST(cr.id AS STRING) id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria` cr WHERE concept_id IN (1305058,35603563,937368,1593700,45892883,929638,1151789,35200139,40161532,44816294,1592513,1511348,19010482,1119119,912263) AND full_text LIKE '%_rank1]%') a ON (c.path LIKE CONCAT('%.',a.id,'.%') OR c.path LIKE CONCAT('%.',a.id) OR c.path LIKE CONCAT(a.id,'.%') OR c.path=a.id) WHERE c.is_standard=1 AND c.is_selectable=1),
drug_set AS (SELECT DISTINCT ca.descendant_id concept_id FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_criteria_ancestor` ca JOIN drug_roots d ON ca.ancestor_id=d.concept_id),
eligible AS (SELECT p.person_id,p.birth_datetime dob,p.sex_at_birth_concept_id,s.age_at_cdr,s.has_ehr_data FROM `wb-silky-artichoke-2408.C2024Q3R8.person` p JOIN `wb-silky-artichoke-2408.C2024Q3R8.cb_search_person` s USING(person_id) WHERE s.age_at_cdr BETWEEN 18 AND 125 AND p.sex_at_birth_concept_id IN (45880669,45878463) AND s.has_whole_genome_variant=1 AND NOT EXISTS (SELECT 1 FROM `wb-silky-artichoke-2408.C2024Q3R8.death` d WHERE d.person_id=p.person_id)),
case_gate AS (SELECT person_id,MAX(ndate)>=2 case_gate FROM (SELECT ev.person_id,ev.concept_id,COUNT(DISTINCT ev.entry_date) ndate FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_search_all_events` ev JOIN eligible e USING(person_id) JOIN case_set c USING(concept_id) WHERE ev.is_standard=1 GROUP BY ev.person_id,ev.concept_id) GROUP BY person_id),
event_flags AS (SELECT ev.person_id,COUNTIF(x.concept_id IS NOT NULL)>0 any_excluded_condition,COUNTIF(d.concept_id IS NOT NULL)>0 any_excluded_drug FROM `wb-silky-artichoke-2408.C2024Q3R8.cb_search_all_events` ev JOIN eligible e USING(person_id) LEFT JOIN exclude_set x USING(concept_id) LEFT JOIN drug_set d USING(concept_id) WHERE ev.is_standard=1 AND (x.concept_id IS NOT NULL OR d.concept_id IS NOT NULL) GROUP BY ev.person_id),
condition_counts AS (SELECT c.person_id,COUNT(DISTINCT DATE(c.condition_start_datetime)) qualifying_dates,COUNT(DISTINCT IF(a.concept_id IS NULL,DATE(c.condition_start_datetime),NULL)) cutaneous_dates,COUNT(DISTINCT IF(a.concept_id IS NOT NULL,DATE(c.condition_start_datetime),NULL)) arthritis_dates,COUNT(*) qualifying_records,COUNTIF(c.condition_start_datetime IS NULL) undated_records FROM `wb-silky-artichoke-2408.C2024Q3R8.condition_occurrence` c JOIN eligible e USING(person_id) JOIN case_set s ON c.condition_concept_id=s.concept_id LEFT JOIN arthritis_set a ON c.condition_concept_id=a.concept_id GROUP BY c.person_id),
visits AS (SELECT v.person_id,COUNT(DISTINCT v.visit_start_date) visit_dates,MIN(v.visit_start_date) first_visit,MAX(v.visit_start_date) last_visit,DATE_DIFF(MAX(v.visit_start_date),MIN(v.visit_start_date),DAY) visit_span_days FROM `wb-silky-artichoke-2408.C2024Q3R8.visit_occurrence` v JOIN eligible e USING(person_id) WHERE v.visit_type_concept_id != 44818519 AND v.visit_start_date IS NOT NULL GROUP BY v.person_id)
SELECT e.*,COALESCE(g.case_gate,FALSE) case_gate,COALESCE(f.any_excluded_condition,FALSE) any_excluded_condition,COALESCE(f.any_excluded_drug,FALSE) any_excluded_drug,COALESCE(c.qualifying_dates,0) qualifying_dates,COALESCE(c.cutaneous_dates,0) cutaneous_dates,COALESCE(c.arthritis_dates,0) arthritis_dates,COALESCE(c.qualifying_records,0) qualifying_records,COALESCE(c.undated_records,0) undated_records,COALESCE(v.visit_dates,0) visit_dates,v.first_visit,v.last_visit,v.visit_span_days FROM eligible e LEFT JOIN case_gate g USING(person_id) LEFT JOIN event_flags f USING(person_id) LEFT JOIN condition_counts c USING(person_id) LEFT JOIN visits v USING(person_id)